entries[164721] = { ["name"] = "Herausforderungskarte: Robenräuber Robert", ["text"] = "Rang 6\nWird beim Aufheben gebunden\nEinzigartig: Herausforderungskarte (1)\n\"Einem Vertreter der Kampfgilde überreichen, um Robenräuber Robert herauszufordern. Ihr könnt nur jeweils eine Herausforderungskarte besitzen.\"\nVerkaufspreis:" }
entries[164731] = { ["name"] = "Verzauberter Schleier", ["text"] = "Questgegenstand\nBenutzen: Verschmelzt mit den Schatten und verbergt Euch vor allen bis auf den aufmerksamsten Zielen." }
entries[164732] = { ["name"] = "Üb3r-Konstrukt: Bummbots mit kurzer Lunte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Beschwört eine Armee von Bummbots mit kurzer Lunte, die den Zaubernden 20 Sek. lang unterstützt. (3 Sek. Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (50)" }
entries[164733] = { ["name"] = "Synchronfaden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nIn der Zeit verschobener Stoff aus Kul Tiras und Zandalar erscheint öfter in der Welt.\nBenutzen: Ermöglicht Synchronschneidern, in Kul Tiras und Zandalar Risse im Gewebe der Zeit zu flicken.\nBenötigt Schneiderei von Kul Tiras (150)\n\"Ein Stich zur rechten Zeit sorgt dafür, dass die Welt nicht auseinanderfällt.\"" }
entries[164734] = { ["name"] = "Üb3r-Konstrukt: Üb3r-aufgemotzte Zielattrappe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Beschwört eine Üb3r-aufgemotzte Zielattrappe, die den Zaubernden 20 Sek. lang unterstützt. (3 Sek. Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (50)" }
entries[164735] = { ["name"] = "Klinge des gefallenen Verteidigers", ["text"] = "Questgegenstand" }
entries[164738] = { ["name"] = "Üb3r-Konstrukt: Üb3rwächt3r Mk. X8.0", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Beschwört einen Üb3rwächt3r Mk. X8.0, der den Zaubernden 20 Sek. lang unterstützt. (3 Sek. Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (50)" }
entries[164740] = { ["name"] = "Üb3r-Schrauber", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nErmöglicht dem Ingenieur, Üb3r-Konstrukte anzufertigen.\nBenutzen: Beschwört ein Üb3r-Konstrukt, das den Zaubernden 20 Sek. lang unterstützt. Wenn kein Üb3r-Konstrukt festgelegt ist, erscheint ein zufälliges. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (150)" }
entries[164741] = { ["name"] = "Unbeständige Azeritgranate", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 5 min (Realzeit)\nBenutzen: Fügt allen Gegnern innerhalb von 7 Metern um den Einschlagsort 10 bis 16 Arkanschaden zu. (5 Sek. Abklingzeit)\nGewährt die Fähigkeit 'Azeritgranate'." }
entries[164742] = { ["name"] = "Kriecherminenteile", ["text"] = "Questgegenstand\n\"Wiederverwertbare Teile\"" }
entries[164745] = { ["name"] = "Waffenstapel", ["text"] = "Questgegenstand\nBenutzen: Platziert einen Waffenstapel am Zielort, um Einwohner in der Nähe zu rekrutieren. Diese werden sich bewaffnen und Gegner angreifen. (15 Sek. Abklingzeit)" }
