entries[164759] = { ["name"] = "Tuch der Illidari", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\nKlassen: Dämonenjäger\nVerkaufspreis:" }
entries[164760] = { ["name"] = "Kriegsgleve der Illidari", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Kriegsgleve\n5 - 8 Schaden Geschwindigkeit 2.60\n(2.5 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[164761] = { ["name"] = "Xal'atath, Klinge des Schwarzen Imperiums", ["text"] = "Questgegenstand\nEinzigartig\n\"Xal'atath hat ihren eigenen Willen. Dieses Artefakt war einst eine begehrte Waffe unter Priestern und wurde gegen die Brennende Legion eingesetzt. Doch jetzt hat sie ihre Macht verloren und ist im Ruhezustand. Noch.\"" }
entries[164762] = { ["name"] = "Streitross von Kul Tiras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer Streitross von Kul Tiras oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Militär von Kul Tiras rühmt sich mit ihrer Überlegenheit sowohl zur See als auch zu Land, durch ihre riesige Flotte sowie die gepanzerte Kavallerie.\"\nErfolg:\nVerbündete Völker: Kul Tiraner" }
entries[164763] = { ["name"] = "Dreizack der Tiefsee", ["text"] = "Questgegenstand\n\"Wenn Ihr ihn an Euer Ohr haltet, könnt Ihr das Meer hören.\"" }
entries[164764] = { ["name"] = "Dreizackkopfstück", ["text"] = "Questgegenstand\nDie Stimme des Ozeans wird Euch schützen.\n\"Die grausamen Zacken könnten als brutale Nahkampfwaffe dienen. Mit dem Dreizackschaft verbinden.\"" }
entries[164766] = { ["name"] = "Iwens Verzauberungsrute", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nGewährt beim Entzaubern zusätzliche Ressourcen.\nBenutzen: Verbraucht einen trüben Kristall, um einen inaktiven Golem zum Leben zu erwecken. (5 Sek. Abklingzeit)\nBenötigt Verzauberkunst von Kul Tiras (150)\n\"Vor lauter Drustmagie surrt diese Rute. Kann auch wie jede geringere runenverzierte Rute verwendet werden.\"" }
entries[164767] = { ["name"] = "Unbearbeiteter Azeritsplitter", ["text"] = "Questgegenstand\nEinzigartig (100)" }
entries[164770] = { ["name"] = "Blitzableiter der Treulosen", ["text"] = "Questgegenstand\n\"Wird von den Treulosen verwendet, um ihre Sethrakmagie für finstere Zwecke zu kanalisieren...\"" }
entries[164772] = { ["name"] = "Pfeife des Kul Tiranischen Waisenkindes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Das Waisenkind rufen und fortschicken, dessen Beaufsichtigung Ihr während der Kinderwoche übernommen habt.\nBenötigt Kinderwoche" }
entries[164773] = { ["name"] = "Gryzix' Dekodierer", ["text"] = "Questgegenstand\n\"Kann verschlüsselte Dokumente von Azshara bis Zangamarschen dechiffrieren. Kann verwendet werden, um den Bauplan des Üb3r-Schraubers zu entschlüsseln.\"" }
entries[164774] = { ["name"] = "Entschlüsseltes Nachrichtenmodul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine entschlüsselte Nachricht. Die Kopfzeile lautet 'Tagebuch von Mogul Ratztunk'\"\n<Zum Lesen rechtsklicken>" }
entries[164778] = { ["name"] = "Abyssisches Szepter", ["text"] = "Questgegenstand\n\"Eines der wertvollsten Artefakte der Gezeitenweisen. In den richtigen Händen gewährt es dem Anwender große Macht über das Meer.\"" }
