entries[165019] = { ["name"] = "Boshafter schwarzer Kriegssäbler", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren boshaften schwarzen Kriegssäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese großen Katzen bringen als Geschenk nur die abgetrennten Gliedmaßen Eurer Gegner heim.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1" }
entries[165020] = { ["name"] = "Boshaftes schwarzes Knochenross", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares boshaftes schwarzes Knochenross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese Skelettrösser kennen keine Furcht, brauchen kein Futter und können unvorstellbar große Distanzen zurücklegen.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
