entries[165566] = { ["name"] = "Signet des Lordadmirals", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+5 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 12.\nAndenken des entschlossenen Kommandanten (0/2)\nDaelin Prachtmeers Säbel\nSignet des Lordadmirals\n(2) Set : Eure automatischen Angriffe sind von der Kälte der hohen See beeinflusst, fügen Eurem Ziel 82 Frostschaden zu und verringern seine Bewegungsgeschwindigkeit 4 Sek. lang um 10%.\nVerkaufspreis:" }
entries[165567] = { ["name"] = "Siegel des Zandalariimperiums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+5 Ausdauer\nErhöht Eure Tempowertung um + 10.\n+ 8 Vielseitigkeit\nGabe der Loa (0/2)\nSiegel des Zandalariimperiums\nSchleier des Loaverehrers\n(2) Set : Euer Primärwert wird um 45 erhöht, während Ihr Euch in Zuldazar befindet.\nVerkaufspreis:" }
entries[165568] = { ["name"] = "Anrufung von Yu'lon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nBenutzen: Befiehlt einer Beschwörung von Yu'lon, Euer Ziel anzugreifen. Sie verursacht 191 Naturschaden, der auf das Ziel und alle Gegner in der Nähe aufgeteilt wird. Der Schaden wird erhöht, wenn mehrere Gegner getroffen werden. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[165569] = { ["name"] = "Zauberschutz der Umhüllung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nBenutzen: Hüllt bis zu 5 Verbündete im Zielbereich 10 Sek. lang in geteilte Schilde, die für alle Ziele zusammen bis zu [ 458 * (1 + Vielseitigkeit)] Schaden verhindern. Je mehr Verbündete geschützt werden, desto mehr Schaden wird insgesamt verhindert. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[165570] = { ["name"] = "Anker der ewigen Kälte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nAnlegen: Eure Nahkampffähigkeiten, die Schaden verursachen, belegen das Ziel mit 'Ewige Kälte'. Dies verursacht alle 3 Sek. 1 Frostschaden und verringert die Bewegungsgeschwindigkeit um 2%. Bis zu 10-mal stapelbar. Hält 12 Sek. lang an. (750ms Abklingzeit)\nVerkaufspreis:" }
entries[165571] = { ["name"] = "Strahlender Span", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nAnlegen: Solange sich keine Verbündeten innerhalb von 5 Metern um Euch befinden, erhaltet Ihr alle 2 Sek. 1 kritischen Trefferwert. Bei 10 Stapeln erhaltet Ihr zusätzlich 4 Meisterschaft. Diese Effekte verfallen langsam, wenn Verbündete in der Nähe sind, die diesen Gegenstand nicht tragen.\nVerkaufspreis:" }
entries[165572] = { ["name"] = "Piepsender oszillierender Wirbelenergiereaktor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nAnlegen: Euer kritischer Trefferwert wird alle 2 Sek. um 3 erhöht, bis auf einen maximalen kritischen Trefferwert von ( 3 * 6), der 6 Sek. lang anhält. Danach verringert er sich, bis das Gerät sich für 6 Sek. ausschaltet. Dieser Zyklus wiederholt sich alle 32 Sek.\nBenutzen: Behält für 6 Sek. Eure derzeitige Oszillation bei. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[165573] = { ["name"] = "Diamantbeschichtetes Refraktionsprisma", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\nAnlegen: Verleiht Euch alle 10 Sek. einen Absorptionsschild in Höhe von [ 82 * (1 + Vielseitigkeit)], bis zu einer maximalen Absorption von [( 82 * (1 + Vielseitigkeit)) * 5].\nVerkaufspreis:" }
entries[165574] = { ["name"] = "Grongs Urfuror", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nBenutzen: Verfällt in eine Dschungelwut und verursacht im Verlauf von 4 Sek. ( 93 * 5) körperlichen Schaden, der auf Gegner in der Nähe aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht. Während die Wut anhält, könnt Ihr Euch weder bewegen noch Fähigkeiten einsetzen. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[165576] = { ["name"] = "Kodex des Gezeitensturms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nBenutzen: Entfesselt eine Welle von 6 Gezeitenelementaren, die über Euer Ziel hereinbrechen, explodieren und dabei jeweils 52 Frostschaden verursachen, der unter allen Gegnern in der Nähe aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht. (1.5Min. Abklingzeit) (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[165577] = { ["name"] = "Bwonsamdis Handel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\nAnlegen: Absorbiert bis zu 2236 Schaden eines Angriffs, der Euch töten würde. Wenn dieser Effekt auftritt, werdet Ihr sofort um 434 Gesundheit geheilt und erhaltet dann 'Bwonsamdis Handel', wodurch Heilung in Höhe von 60% des ursprünglich verhinderten Schadens absorbiert wird. Dies kann nur einmal alle 6 Min. geschehen.\nVerkaufspreis:" }
entries[165578] = { ["name"] = "Spiegel des geteilten Schicksals", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nBenutzen: Stellt beim Ziel 4580 Gesundheit wieder her, aber verflucht Euch dabei selbst, wodurch die nächsten 136 erhaltene Heilung absorbiert werden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[165579] = { ["name"] = "Kimbuls messerscharfe Kralle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nAnlegen: Eure Schaden verursachenden Angriffe haben eine Chance, das Ziel mit Klauen zu schlagen und ihm im Verlauf von 6 Sek. 20 körperlichen Blutungsschaden zuzufügen. Wenn Ihr das Ziel von hinten mit den Klauen trefft, entzieht Ihr ihm 50% des verursachten Schadens als Gesundheit. (6s Abklingzeit)\nVerkaufspreis:" }
entries[165580] = { ["name"] = "Rasant ausschlagende gigavoltgeladene Erfindung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nBenutzen: Erhöht Euer Tempo um 4 und Eure Geschwindigkeit um 1 . Dieser Effekt ist im Verlauf von 10 Sek. bis zu 15-Mal stapelbar. Die Stapel erhöhen sich immer schneller, je mehr die gigavoltgeladene Erfindung beschleunigt. Die Erfindung läuft insgesamt 18 Sek. lang. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[165581] = { ["name"] = "Pa'kus Wappen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, 15 Sek. lang Euer Tempo um 24 und Eure Bewegungsgeschwindigkeit um 7 zu erhöhen.\nBenutzen: Fliegt zu einem nahen Totem von Pa'ku. Kann nur im Freien in Dazar'alor eingesetzt werden. (20 Min Abklingzeit)\nVerkaufspreis:" }
